-- roles and grants of the prod database memes_general (environment general).
-- GENERATED by `python -m sync.roles --env general` (generator version 1, registry digest 264f92c22d4b6073).
-- Do not edit: tests/sync/test_roles.py fails when this file is not what the generator produces from sync/registry.py.
--
-- Contract: docs/superpowers/specs/2026-11-12-environment-data-sync/interfaces.md section h.
-- Re-applied at every release (idempotent, one transaction): everything the five roles hold in schema public is revoked and the
-- exact list granted again, then a verification block raises when the effective privileges differ from the registry.
-- Run it with:  psql -X -v ON_ERROR_STOP=1 -d <database> -f roles.<env>.sql   (as the bootstrap superuser, or as the owner role).
-- No credential is in this file. A role created here has no credential and cannot log in until provision.sh sets one with an
-- ALTER ROLE statement fed through a psql variable; a re-apply never touches credentials.
-- MAINTAIN needs PostgreSQL 17 or later and is skipped on older servers (the local CI service container is 16).

BEGIN;

-- 1. Guard: this file must never run against another database.
DO $guard$
BEGIN
    IF current_database() <> 'memes_general' THEN
        RAISE EXCEPTION 'roles file of database memes_general applied to database %', current_database();
    END IF;
END
$guard$;

-- 2. Roles (superuser only). Attributes, connection limits, role settings, no memberships, owner of the database.
DO $roles$
DECLARE
    r text;
    m record;
BEGIN
    IF NOT (SELECT rolsuper FROM pg_roles WHERE rolname = current_user) THEN
        RAISE NOTICE 'not a superuser: roles, attributes and the database owner are verified below, not changed';
        RETURN;
    END IF;
    FOREACH r IN ARRAY ARRAY['memes_general_owner', 'memes_general_app', 'memes_general_sync_w', 'memes_general_sync_r', 'memes_general_ro'] LOOP
        IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) THEN
            EXECUTE format('CREATE ROLE %I', r);
        END IF;
    END LOOP;
    ALTER ROLE "memes_general_owner" WITH LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS INHERIT CONNECTION LIMIT 3;
    ALTER ROLE "memes_general_app" WITH LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS INHERIT CONNECTION LIMIT 24;
    ALTER ROLE "memes_general_sync_w" WITH LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS INHERIT CONNECTION LIMIT 3;
    ALTER ROLE "memes_general_sync_r" WITH LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS INHERIT CONNECTION LIMIT 3;
    ALTER ROLE "memes_general_ro" WITH LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS INHERIT CONNECTION LIMIT 2;
    ALTER ROLE "memes_general_owner" RESET ALL;
    ALTER ROLE "memes_general_app" RESET ALL;
    ALTER ROLE "memes_general_sync_w" RESET ALL;
    ALTER ROLE "memes_general_sync_r" RESET ALL;
    ALTER ROLE "memes_general_ro" RESET ALL;
    ALTER ROLE "memes_general_app" SET statement_timeout = '10s';
    ALTER ROLE "memes_general_app" SET idle_in_transaction_session_timeout = '30s';
    ALTER ROLE "memes_general_app" SET lock_timeout = '3s';
    FOR m IN
        SELECT granted.rolname AS granted, member.rolname AS member, grantor.rolname AS grantor
        FROM pg_auth_members am
        JOIN pg_roles granted ON granted.oid = am.roleid
        JOIN pg_roles member ON member.oid = am.member
        JOIN pg_roles grantor ON grantor.oid = am.grantor
        WHERE member.rolname = ANY(ARRAY['memes_general_owner', 'memes_general_app', 'memes_general_sync_w', 'memes_general_sync_r', 'memes_general_ro'])
    LOOP
        EXECUTE format('REVOKE %I FROM %I GRANTED BY %I', m.granted, m.member, m.grantor);
    END LOOP;
    ALTER DATABASE "memes_general" OWNER TO "memes_general_owner";
    -- The database markers (provision.sh and the release runbook set them as the owner): since PostgreSQL 15 a database owner may not
    -- ALTER DATABASE ... SET a custom parameter without the SET privilege on that parameter, and only a superuser can grant it.
    IF current_setting('server_version_num')::int >= 150000 THEN
        EXECUTE 'REVOKE ALL ON PARAMETER memes.environment, memes.state, memes.revision FROM "memes_general_app", "memes_general_sync_w", "memes_general_sync_r", "memes_general_ro"';
        EXECUTE 'GRANT SET ON PARAMETER memes.environment, memes.state, memes.revision TO "memes_general_owner"';
    END IF;
END
$roles$;

-- 3. Database and schema level: no PUBLIC access, per-role CONNECT only, nobody but the owner creates objects.
REVOKE ALL ON DATABASE "memes_general" FROM PUBLIC;
REVOKE ALL ON DATABASE "memes_general" FROM "memes_general_app", "memes_general_sync_w", "memes_general_sync_r", "memes_general_ro";
GRANT CONNECT ON DATABASE "memes_general" TO "memes_general_app", "memes_general_sync_w", "memes_general_sync_r", "memes_general_ro";
REVOKE CREATE ON SCHEMA public FROM PUBLIC;
REVOKE ALL ON SCHEMA public FROM "memes_general_app", "memes_general_sync_w", "memes_general_sync_r", "memes_general_ro";
GRANT USAGE ON SCHEMA public TO "memes_general_app", "memes_general_sync_w", "memes_general_sync_r", "memes_general_ro";
-- No default privileges for any role except the owner's own: a new table is unreachable until this file runs again.
ALTER DEFAULT PRIVILEGES FOR ROLE "memes_general_owner" REVOKE ALL ON TABLES FROM "memes_general_app", "memes_general_sync_w", "memes_general_sync_r", "memes_general_ro";
ALTER DEFAULT PRIVILEGES FOR ROLE "memes_general_owner" IN SCHEMA public REVOKE ALL ON TABLES FROM "memes_general_app", "memes_general_sync_w", "memes_general_sync_r", "memes_general_ro";
ALTER DEFAULT PRIVILEGES FOR ROLE "memes_general_owner" REVOKE ALL ON SEQUENCES FROM "memes_general_app", "memes_general_sync_w", "memes_general_sync_r", "memes_general_ro";
ALTER DEFAULT PRIVILEGES FOR ROLE "memes_general_owner" IN SCHEMA public REVOKE ALL ON SEQUENCES FROM "memes_general_app", "memes_general_sync_w", "memes_general_sync_r", "memes_general_ro";

-- 4. Object grants: revoke everything first, then grant exactly the list (this is what removes drift).
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM "memes_general_app", "memes_general_sync_w", "memes_general_sync_r", "memes_general_ro";
REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM "memes_general_app", "memes_general_sync_w", "memes_general_sync_r", "memes_general_ro";
DO $grants$
DECLARE
    t text;
    s text;
BEGIN
    IF to_regclass('public.alembic_version') IS NULL THEN
        RAISE NOTICE 'no schema yet (no alembic_version): table grants skipped, apply this file again after the first migration';
        RETURN;
    END IF;
    -- memes_general_app: reads class D, reads and writes exactly the class P tables, nothing on class X or alembic_version.
    GRANT SELECT ON TABLE
            "concept_image_sets", "concept_images", "concept_text_sets", "concept_texts", "concepts",
            "description_lemmas", "description_note_embeddings", "description_note_lemmas",
            "description_notes", "embeddings", "image_description_embeddings", "image_description_feedback",
            "image_descriptions", "image_extras", "images", "meme_profile_situation_embeddings",
            "meme_profile_values", "meme_profiles", "ocr_lemmas", "ocr_texts", "popularity_absorptions",
            "tags"
            TO "memes_general_app";
    GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE
            "meme_impressions", "meme_saves", "meme_text_ratings", "search_history", "search_history_tags",
            "search_not_found"
            TO "memes_general_app";
    -- memes_general_sync_w: writes class D, reads alembic_version, three ratings columns (no text), no TEMP, nothing on class P or X.
    GRANT SELECT, INSERT, UPDATE ON TABLE
            "concept_image_sets", "concept_images", "concept_text_sets", "concept_texts", "concepts",
            "description_lemmas", "description_note_embeddings", "description_note_lemmas",
            "description_notes", "embeddings", "image_description_embeddings", "image_description_feedback",
            "image_descriptions", "image_extras", "images", "meme_profile_situation_embeddings",
            "meme_profile_values", "meme_profiles", "ocr_lemmas", "ocr_texts", "popularity_absorptions",
            "tags"
            TO "memes_general_sync_w";
    -- DELETE only where the promote replaces rows per image (never images, an upsert table or a global set).
    GRANT DELETE ON TABLE
            "description_lemmas", "description_note_embeddings", "description_note_lemmas",
            "description_notes", "embeddings", "image_description_embeddings", "image_description_feedback",
            "image_descriptions", "image_extras", "meme_profile_situation_embeddings", "meme_profile_values",
            "meme_profiles", "ocr_lemmas", "ocr_texts", "tags"
            TO "memes_general_sync_w";
    GRANT SELECT ON TABLE alembic_version TO "memes_general_sync_w";
    GRANT SELECT (image_id, query_hash, updated_at) ON TABLE meme_text_ratings TO "memes_general_sync_w";
    IF current_setting('server_version_num')::int >= 170000 THEN
        EXECUTE format('GRANT MAINTAIN ON TABLE %s TO %I',
            (SELECT string_agg(quote_ident(x), ', ') FROM unnest(ARRAY[
                'concept_image_sets', 'concept_images', 'concept_text_sets', 'concept_texts', 'concepts',
                'description_lemmas', 'description_note_embeddings', 'description_note_lemmas',
                'description_notes', 'embeddings', 'image_description_embeddings', 'image_description_feedback',
                'image_descriptions', 'image_extras', 'images', 'meme_profile_situation_embeddings',
                'meme_profile_values', 'meme_profiles', 'ocr_lemmas', 'ocr_texts', 'popularity_absorptions',
                'tags'
            ]) x),
            'memes_general_sync_w');
    END IF;
    -- memes_general_sync_r: reads the class P tables, alembic_version and images.id only.
    GRANT SELECT ON TABLE
            "meme_impressions", "meme_saves", "meme_text_ratings", "search_history", "search_history_tags",
            "search_not_found"
            TO "memes_general_sync_r";
    GRANT SELECT ON TABLE alembic_version TO "memes_general_sync_r";
    GRANT SELECT (id) ON TABLE images TO "memes_general_sync_r";
    -- memes_general_ro: reads everything except the reader-activity text tables.
    GRANT SELECT ON TABLE
            "batch_runs", "comics", "comics_candidate_images", "comics_candidates", "comics_panels",
            "concept_image_sets", "concept_images", "concept_text_sets", "concept_texts", "concepts",
            "description_lemmas", "description_note_embeddings", "description_note_lemmas",
            "description_notes", "duplicate_decisions", "embeddings", "image_classifications", "image_cuts",
            "image_description_embeddings", "image_description_feedback", "image_descriptions", "image_extras",
            "image_metrics", "image_processing_status", "images", "meme_impressions",
            "meme_profile_situation_embeddings", "meme_profile_values", "meme_profiles", "meme_saves",
            "ocr_lemmas", "ocr_text_embeddings", "ocr_texts", "popularity_absorptions", "process_events",
            "processing_errors", "search_not_found", "statistics_snapshots", "tags", "tmp_clusters",
            "tmp_duplicates", "trend_sources", "trends_run_results", "alembic_version"
            TO "memes_general_ro";
    -- Sequences. memes_general_sync_w: the integer-id class D tables (setval after a load). memes_general_app: the serial id of a class P table.
    FOREACH t IN ARRAY ARRAY[
        'concept_image_sets', 'concept_images', 'concept_text_sets', 'concept_texts', 'concepts'
    ] LOOP
        s := pg_get_serial_sequence(format('public.%I', t), 'id');
        IF s IS NULL THEN RAISE EXCEPTION 'table % has no serial id sequence', t; END IF;
        EXECUTE format('GRANT USAGE, SELECT, UPDATE ON SEQUENCE %s TO %I', s, 'memes_general_sync_w');
    END LOOP;
    FOREACH t IN ARRAY ARRAY[
        'meme_impressions'
    ] LOOP
        s := pg_get_serial_sequence(format('public.%I', t), 'id');
        IF s IS NULL THEN RAISE EXCEPTION 'table % has no serial id sequence', t; END IF;
        EXECUTE format('GRANT USAGE, SELECT ON SEQUENCE %s TO %I', s, 'memes_general_app');
    END LOOP;
END
$grants$;

-- 5. Verification: the effective privileges (PUBLIC and memberships included) must equal the registry; otherwise the whole file rolls back.
DO $verify$
DECLARE
    bad text;
    five text[] := ARRAY['memes_general_owner', 'memes_general_app', 'memes_general_sync_w', 'memes_general_sync_r', 'memes_general_ro'];
    four text[] := ARRAY['memes_general_app', 'memes_general_sync_w', 'memes_general_sync_r', 'memes_general_ro'];
    privs text[] := ARRAY['SELECT', 'INSERT', 'UPDATE', 'DELETE', 'TRUNCATE', 'REFERENCES', 'TRIGGER'];
    can_maintain boolean := current_setting('server_version_num')::int >= 170000;
BEGIN
    SELECT string_agg(r, ', ') INTO bad FROM unnest(five) r WHERE NOT EXISTS (
        SELECT 1 FROM pg_roles x WHERE x.rolname = r AND x.rolcanlogin AND NOT x.rolsuper AND NOT x.rolcreatedb
            AND NOT x.rolcreaterole AND NOT x.rolreplication AND NOT x.rolbypassrls AND x.rolinherit
            AND x.rolconnlimit = CASE r
                WHEN 'memes_general_owner' THEN 3
                WHEN 'memes_general_app' THEN 24
                WHEN 'memes_general_sync_w' THEN 3
                WHEN 'memes_general_sync_r' THEN 3
                WHEN 'memes_general_ro' THEN 2
            END);
    IF bad IS NOT NULL THEN RAISE EXCEPTION 'role attributes or connection limit differ from the contract: %', bad; END IF;
    SELECT string_agg(member.rolname || ' in ' || granted.rolname, ', ') INTO bad FROM pg_auth_members am
        JOIN pg_roles granted ON granted.oid = am.roleid JOIN pg_roles member ON member.oid = am.member
        WHERE member.rolname = ANY(five);
    IF bad IS NOT NULL THEN RAISE EXCEPTION 'role memberships found: %', bad; END IF;
    IF (SELECT pg_get_userbyid(datdba) FROM pg_database WHERE datname = current_database()) <> 'memes_general_owner' THEN
        RAISE EXCEPTION 'the owner of the database is not memes_general_owner';
    END IF;
    SELECT string_agg(x.rolname, ', ') INTO bad FROM unnest(five) r JOIN pg_roles x ON x.rolname = r
        WHERE NOT has_database_privilege(x.oid, current_database(), 'CONNECT');
    IF bad IS NOT NULL THEN RAISE EXCEPTION 'role without CONNECT: %', bad; END IF;
    SELECT string_agg(x.rolname, ', ') INTO bad FROM unnest(four) r JOIN pg_roles x ON x.rolname = r
        WHERE has_database_privilege(x.oid, current_database(), 'CREATE')
            OR has_database_privilege(x.oid, current_database(), 'TEMPORARY')
            OR has_schema_privilege(x.oid, 'public', 'CREATE');
    IF bad IS NOT NULL THEN RAISE EXCEPTION 'role with CREATE or TEMP: %', bad; END IF;
    IF EXISTS (SELECT 1 FROM pg_namespace n, aclexplode(n.nspacl) a WHERE n.nspname = 'public' AND a.grantee = 0 AND a.privilege_type = 'CREATE') THEN
        RAISE EXCEPTION 'PUBLIC can create in schema public';
    END IF;
    IF EXISTS (SELECT 1 FROM pg_database d, aclexplode(d.datacl) a WHERE d.datname = current_database() AND a.grantee = 0) THEN
        RAISE EXCEPTION 'PUBLIC holds a privilege on the database';
    END IF;
    SELECT string_agg(a.privilege_type || ' for ' || x.rolname, ', ') INTO bad
        FROM pg_default_acl d, aclexplode(d.defaclacl) a JOIN pg_roles x ON x.oid = a.grantee
        WHERE x.rolname = ANY(four);
    IF bad IS NOT NULL THEN RAISE EXCEPTION 'default privileges found: %', bad; END IF;
    IF current_setting('server_version_num')::int >= 150000 THEN
        SELECT string_agg(x || ' on ' || m, ', ') INTO bad
        FROM unnest(ARRAY['memes.environment', 'memes.state', 'memes.revision']) m CROSS JOIN unnest(five) x
        WHERE (x = 'memes_general_owner') <> has_parameter_privilege(x, m, 'SET');
        IF bad IS NOT NULL THEN RAISE EXCEPTION 'SET privilege on the database markers differs from the contract (owner only): %', bad; END IF;
    END IF;
    IF to_regclass('public.alembic_version') IS NULL THEN
        RAISE NOTICE 'no schema yet: object privileges not verified';
        RETURN;
    END IF;
    IF can_maintain THEN privs := privs || ARRAY['MAINTAIN']; END IF;
    WITH expected(item) AS (
        SELECT unnest(ARRAY[
            'memes_general_app|concept_image_sets|SELECT', 'memes_general_app|concept_images|SELECT',
            'memes_general_app|concept_text_sets|SELECT', 'memes_general_app|concept_texts|SELECT',
            'memes_general_app|concepts|SELECT', 'memes_general_app|description_lemmas|SELECT',
            'memes_general_app|description_note_embeddings|SELECT',
            'memes_general_app|description_note_lemmas|SELECT', 'memes_general_app|description_notes|SELECT',
            'memes_general_app|embeddings|SELECT', 'memes_general_app|image_description_embeddings|SELECT',
            'memes_general_app|image_description_feedback|SELECT',
            'memes_general_app|image_descriptions|SELECT', 'memes_general_app|image_extras|SELECT',
            'memes_general_app|images|SELECT', 'memes_general_app|meme_profile_situation_embeddings|SELECT',
            'memes_general_app|meme_profile_values|SELECT', 'memes_general_app|meme_profiles|SELECT',
            'memes_general_app|ocr_lemmas|SELECT', 'memes_general_app|ocr_texts|SELECT',
            'memes_general_app|popularity_absorptions|SELECT', 'memes_general_app|tags|SELECT',
            'memes_general_app|meme_impressions|SELECT', 'memes_general_app|meme_impressions|INSERT',
            'memes_general_app|meme_impressions|UPDATE', 'memes_general_app|meme_impressions|DELETE',
            'memes_general_app|meme_saves|SELECT', 'memes_general_app|meme_saves|INSERT',
            'memes_general_app|meme_saves|UPDATE', 'memes_general_app|meme_saves|DELETE',
            'memes_general_app|meme_text_ratings|SELECT', 'memes_general_app|meme_text_ratings|INSERT',
            'memes_general_app|meme_text_ratings|UPDATE', 'memes_general_app|meme_text_ratings|DELETE',
            'memes_general_app|search_history|SELECT', 'memes_general_app|search_history|INSERT',
            'memes_general_app|search_history|UPDATE', 'memes_general_app|search_history|DELETE',
            'memes_general_app|search_history_tags|SELECT', 'memes_general_app|search_history_tags|INSERT',
            'memes_general_app|search_history_tags|UPDATE', 'memes_general_app|search_history_tags|DELETE',
            'memes_general_app|search_not_found|SELECT', 'memes_general_app|search_not_found|INSERT',
