            'memes_general_sync_w|concept_image_sets|SELECT', 'memes_general_sync_w|concept_image_sets|INSERT',
            'memes_general_sync_w|concept_image_sets|UPDATE', 'memes_general_sync_w|concept_images|SELECT',
