            'memes_general_ro|description_note_lemmas|SELECT', 'memes_general_ro|description_notes|SELECT',
            'memes_general_ro|duplicate_decisions|SELECT', 'memes_general_ro|embeddings|SELECT',
            'memes_general_ro|image_classifications|SELECT', 'memes_general_ro|image_cuts|SELECT',
            'memes_general_ro|image_description_embeddings|SELECT',
            'memes_general_ro|image_description_feedback|SELECT', 'memes_general_ro|image_descriptions|SELECT',
            'memes_general_ro|image_extras|SELECT', 'memes_general_ro|image_metrics|SELECT',
            'memes_general_ro|image_processing_status|SELECT', 'memes_general_ro|images|SELECT',
            'memes_general_ro|meme_impressions|SELECT',
            'memes_general_ro|meme_profile_situation_embeddings|SELECT',
            'memes_general_ro|meme_profile_values|SELECT', 'memes_general_ro|meme_profiles|SELECT',
            'memes_general_ro|meme_saves|SELECT', 'memes_general_ro|ocr_lemmas|SELECT',
            'memes_general_ro|ocr_text_embeddings|SELECT', 'memes_general_ro|ocr_texts|SELECT',
            'memes_general_ro|popularity_absorptions|SELECT', 'memes_general_ro|process_events|SELECT',
            'memes_general_ro|processing_errors|SELECT', 'memes_general_ro|search_not_found|SELECT',
            'memes_general_ro|statistics_snapshots|SELECT', 'memes_general_ro|tags|SELECT',
            'memes_general_ro|tmp_clusters|SELECT', 'memes_general_ro|tmp_duplicates|SELECT',
            'memes_general_ro|trend_sources|SELECT', 'memes_general_ro|trends_run_results|SELECT',
            'memes_general_ro|alembic_version|SELECT'
        ])
        UNION ALL
        SELECT unnest(ARRAY[
            'memes_general_sync_w|concept_image_sets|MAINTAIN', 'memes_general_sync_w|concept_images|MAINTAIN',
            'memes_general_sync_w|concept_text_sets|MAINTAIN', 'memes_general_sync_w|concept_texts|MAINTAIN',
            'memes_general_sync_w|concepts|MAINTAIN', 'memes_general_sync_w|description_lemmas|MAINTAIN',
            'memes_general_sync_w|description_note_embeddings|MAINTAIN',
            'memes_general_sync_w|description_note_lemmas|MAINTAIN',
            'memes_general_sync_w|description_notes|MAINTAIN', 'memes_general_sync_w|embeddings|MAINTAIN',
            'memes_general_sync_w|image_description_embeddings|MAINTAIN',
            'memes_general_sync_w|image_description_feedback|MAINTAIN',
            'memes_general_sync_w|image_descriptions|MAINTAIN', 'memes_general_sync_w|image_extras|MAINTAIN',
            'memes_general_sync_w|images|MAINTAIN',
            'memes_general_sync_w|meme_profile_situation_embeddings|MAINTAIN',
            'memes_general_sync_w|meme_profile_values|MAINTAIN', 'memes_general_sync_w|meme_profiles|MAINTAIN',
            'memes_general_sync_w|ocr_lemmas|MAINTAIN', 'memes_general_sync_w|ocr_texts|MAINTAIN',
            'memes_general_sync_w|popularity_absorptions|MAINTAIN', 'memes_general_sync_w|tags|MAINTAIN'
        ]) WHERE can_maintain
    ), actual(item) AS (
        SELECT r.rolname || '|' || c.relname || '|' || p
        FROM pg_roles r CROSS JOIN pg_class c CROSS JOIN unnest(privs) p
        WHERE r.rolname = ANY(four) AND c.relnamespace = 'public'::regnamespace AND c.relkind IN ('r', 'p', 'v', 'm', 'f')
            AND has_table_privilege(r.oid, c.oid, p)
    )
    SELECT string_agg(item, ', ' ORDER BY item) INTO bad FROM (
        (SELECT 'extra ' || item AS item FROM actual EXCEPT SELECT 'extra ' || item FROM expected)
        UNION ALL
        (SELECT 'missing ' || item FROM expected EXCEPT SELECT 'missing ' || item FROM actual)
    ) d;
    IF bad IS NOT NULL THEN RAISE EXCEPTION 'table privileges differ from the registry: %', left(bad, 600); END IF;
    WITH expected(item) AS (
        SELECT unnest(ARRAY[
            'memes_general_sync_w|meme_text_ratings|image_id|SELECT',
            'memes_general_sync_w|meme_text_ratings|query_hash|SELECT',
            'memes_general_sync_w|meme_text_ratings|updated_at|SELECT',
            'memes_general_sync_r|images|id|SELECT'
        ])
    ), actual(item) AS (
        SELECT coalesce(r.rolname, 'PUBLIC') || '|' || c.relname || '|' || a.attname || '|' || x.privilege_type
        FROM pg_attribute a JOIN pg_class c ON c.oid = a.attrelid
        CROSS JOIN LATERAL aclexplode(a.attacl) x LEFT JOIN pg_roles r ON r.oid = x.grantee
        WHERE a.attacl IS NOT NULL AND c.relnamespace = 'public'::regnamespace AND NOT a.attisdropped
            AND (x.grantee = 0 OR r.rolname = ANY(five))
    )
    SELECT string_agg(item, ', ' ORDER BY item) INTO bad FROM (
        (SELECT 'extra ' || item AS item FROM actual EXCEPT SELECT 'extra ' || item FROM expected)
        UNION ALL
        (SELECT 'missing ' || item FROM expected EXCEPT SELECT 'missing ' || item FROM actual)
    ) d;
    IF bad IS NOT NULL THEN RAISE EXCEPTION 'column privileges differ from the registry: %', left(bad, 600); END IF;
    WITH expected(item) AS (
        SELECT 'memes_general_sync_w' || '|' || pg_get_serial_sequence('public.' || quote_ident(t), 'id') || '|' || p
        FROM unnest(ARRAY[
            'concept_image_sets', 'concept_images', 'concept_text_sets', 'concept_texts', 'concepts'
        ]) t CROSS JOIN unnest(ARRAY['USAGE', 'SELECT', 'UPDATE']) p
        UNION ALL
        SELECT 'memes_general_app' || '|' || pg_get_serial_sequence('public.' || quote_ident(t), 'id') || '|' || p
        FROM unnest(ARRAY[
            'meme_impressions'
        ]) t CROSS JOIN unnest(ARRAY['USAGE', 'SELECT']) p
    ), actual(item) AS (
        SELECT r.rolname || '|public.' || c.relname || '|' || p
        FROM pg_roles r CROSS JOIN pg_class c CROSS JOIN unnest(ARRAY['USAGE', 'SELECT', 'UPDATE']) p
        WHERE r.rolname = ANY(four) AND c.relnamespace = 'public'::regnamespace AND c.relkind = 'S'
            AND has_sequence_privilege(r.oid, c.oid, p)
    )
    SELECT string_agg(item, ', ' ORDER BY item) INTO bad FROM (
        (SELECT 'extra ' || item AS item FROM actual EXCEPT SELECT 'extra ' || item FROM expected)
        UNION ALL
        (SELECT 'missing ' || item FROM expected EXCEPT SELECT 'missing ' || item FROM actual)
    ) d;
    IF bad IS NOT NULL THEN RAISE EXCEPTION 'sequence privileges differ from the registry: %', left(bad, 600); END IF;
END
$verify$;

COMMIT;
